private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder cannot be null");
    }
    if (i < 0 || i >= bb.remaining()) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    bb.position(i);
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b < 128) {
            sb.append((char) b);
        } else if (b < 192) {
            // Invalid continuation byte
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        } else if (b < 224) {
            if (bb.remaining() < 1) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b2 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
        } else if (b < 240) {
            if (bb.remaining() < 2) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
        } else if (b < 248) {
            if (bb.remaining() < 3) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int b4 = bb.get() & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            sb.append((char) (((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F)));
        } else {
            // Invalid leading byte
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return bb.position();
}
