private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    // Assuming this method is part of a class that has a byte array and a capacity field
    // For example:
    // private byte[] bytes;
    // private int capacity;
    // private int size;

    // Calculate the new capacity
    int newCapacity = capacity + size;
    if (newCapacity < 0) {
        throw new OutOfMemoryError("Capacity overflow");
    }

    // Create a new byte array with the new capacity
    byte[] newBytes = new byte[newCapacity];

    // Copy the existing bytes to the new array
    System.arraycopy(bytes, 0, newBytes, 0, size);

    // Update the byte array and capacity
    bytes = newBytes;
    capacity = newCapacity;
}
