import java.io.File;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Vector;

@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    File directory = new File(dir);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("The provided directory does not exist or is not a directory.");
    }

    File[] files = directory.listFiles((d, name) -> name.endsWith(".jar"));
    if (files == null) {
        return;
    }

    for (File file : files) {
        try {
            URL url = file.toURI().toURL();
            cpV.add(url);
            URLClassLoader classLoader = (URLClassLoader) ClassLoader.getSystemClassLoader();
            java.lang.reflect.Method method = URLClassLoader.class.getDeclaredMethod("addURL", URL.class);
            method.setAccessible(true);
            method.invoke(classLoader, url);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
