    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    // Populate the sets with vertices from resultMap
    for (V vertex : resultMap.values()) {
        if (set1.size() <= set2.size()) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
    }

    // Add vertices to the graph
    for (V vertex : set1) {
        target.addVertex(vertex);
    }
    for (V vertex : set2) {
        target.addVertex(vertex);
    }

    // Add edges between the two sets
    for (V v1 : set1) {
        for (V v2 : set2) {
            E edge = target.addEdge(v1, v2);
            if (edge != null) {
