static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        String timeStr = String.format("%08d", timeBucket);
        int year = Integer.parseInt(timeStr.substring(0, 4));
        int month = Integer.parseInt(timeStr.substring(4, 6));
        int day = Integer.parseInt(timeStr.substring(6, 8));

        if (dayStep == 1) {
            return timeBucket;
        } else if (dayStep == 7) {
            day = (day - 1) / 7 * 7 + 1;
        } else if (dayStep == 11) {
            day = (day - 1) / 11 * 11 + 1;
        } else {
            throw new IllegalArgumentException("Unsupported dayStep: " + dayStep);
        }

        return Long.parseLong(String.format("%04d%02d%02d", year, month, day));
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid timeBucket format: " + timeBucket, e);
    }
}
